create table tb_game (ano integer not null, score float(53), id bigint generated by default as identity, genero varchar(50), plataforma varchar(50), titulo varchar(100) not null, descricao_curta varchar(500), descricao_longa TEXT, img_url varchar(255), primary key (id));
create table tb_game_list (id bigint generated by default as identity, nome varchar(255), primary key (id));
create table tb_relacao_game_game_list (posicao integer, game_id bigint not null, list_id bigint not null, primary key (game_id, list_id));
alter table if exists tb_relacao_game_game_list add constraint FKcwtilveb0m2uu64ei544p35tp foreign key (list_id) references tb_game_list;
alter table if exists tb_relacao_game_game_list add constraint FKospte3vmbgy31hqaix63qmbv9 foreign key (game_id) references tb_game;
